import OAuthServerModule, { addOAuthScope } from '../../../src/module'

// The signing keys are generated by the test run and passed in through
// `NUXT_OAUTH_SERVER_PRIVATE_KEY`, so no key material lives in the repository.
export default defineNuxtConfig({
  modules: [
    '@nuxthub/core',
    '@frigear-nu/users',
    '@frigear-nu/admin',
    OAuthServerModule,
    // A service module adding its scopes to the registry (installed after the server: order does not matter).
    (_options: unknown, nuxt: Parameters<typeof addOAuthScope>[0]) => addOAuthScope(nuxt,
      { name: 'inventory:write', description: 'Change the inventory', service: 'Inventory', staffOnly: true },
      { name: 'shop:order', description: 'Shop module description', service: 'Shop' },
    ),
  ],
  runtimeConfig: {
    session: {
      password: 'a-test-only-session-password-at-least-32-chars',
    },
  },
  hub: {
    db: {
      dialect: 'sqlite',
      driver: 'libsql',
      applyMigrationsDuringBuild: false,
    },
  },
  oauthServer: {
    issuer: 'https://id.example.test',
    // Access tokens for every Frigear service: one shared audience, ten minutes.
    accessTokenAudience: 'frigear-services',
    accessTokenTtl: 600,
    scopes: [
      { name: 'groups', label: 'Your groups', description: 'Which groups you belong to', icon: 'i-lucide-users' },
      { name: 'vouchers:read', description: 'See your vouchers', service: 'Vouchers' },
      { name: 'vouchers:write', description: 'Redeem your vouchers', service: 'Vouchers' },
      // The host's details win over the ones the module registered.
      { name: 'shop:order', description: 'Place orders in the shop', service: 'Shop' },
      { name: 'inventory:read', description: 'See the inventory', service: 'Inventory', staffOnly: true },
    ],
    // `/api/test/` stands in for the host's API; the admin API stays closed.
    cors: { origins: ['capacitor://localhost', 'https://app.example.com'], paths: ['/api/test/'] },
    // A mobile app with a fixed client id, created on first use. The fixture runs in dev, so the dev URI counts.
    clients: [{
      id: 'test-mobile',
      name: 'Test mobile',
      redirectUris: ['com.example.test:/auth/callback'],
      devRedirectUris: ['http://localhost:3001/auth/callback'],
      tags: ['mobile'],
    }, {
      // Native only: nothing to open from the user's applications list.
      id: 'test-native',
      name: 'Test native',
      redirectUris: ['com.example.native:/auth/callback'],
    }, {
      // The test turns its row confidential, as if the id had been taken by an application created earlier.
      id: 'test-conflict',
      name: 'Test conflict',
      redirectUris: ['com.example.conflict:/auth/callback'],
    }],
    settings: { pages: { authorize: false, admin: true }, mcp: true },
  },
  // The users admin registers the staff-only `users:read` scope.
  users: { settings: { admin: true } },
})
